mapper.select:
select VALUATION from (
    select fpv.VALUATION,
    @rownum := @rownum + 1 as rn
    from (SELECT @rownum:=0) r,FIN_PRODUCT_VALUATION fpv
    inner join FIN_PRODUCT fp
    on fpv.FINPROD_ID = fp.FINPROD_MARKET_ID
    and fpv.FINPROD_TYPE = #{FIN_PROD_TYPE_F17}
    and fpv.FINPROD_TYPE2 = #{FIN_PROD_TYPE_2_F17}
    and fp.FINPROD_ID=#{finprodId}
    and fpv.VAL_DATE<=#{dealDate}
    order by fpv.VAL_DATE desc
)
where rn = 1

SELECT
100 - IFNULL(sum(fcp.PRIN_AMT), 0)
FROM
FIN_CASH_PLAN fcp
inner join FIN_CASH_INFO fci
on fcp.CASH_ID = fci.CASH_ID
WHERE
fcp.FINPROD_ID = #{finprodId}

AND fcp.MDATE < #{settleDate}
and fci.CASH_TYPE_1 = #{cashType1}

select
prp.BRANCH,
prp.REC_TYPE recType,
prp.AMOUNT +IFNULL((
select
sum(AMOUNT)
from PTL_RECE_POSITION_FLOW prpf
where
prpf.PORTFOLIO_ID = prp.PORTFOLIO_ID
and prpf.FINPROD_ID = prp.FINPROD_ID
and prpf.SEC_ACCT_ID = prp.SEC_ACCT_ID
and prpf.BRANCH = prp.BRANCH
and prpf.INV_AIM = prp.INV_AIM
and prpf.HODING_TYPE = #{POSITION_TYPE_KY}
and prpf.CDATE = prp.CDATE
),0) AMOUNT,
prp.CCY,
prp.INV_AIM
from
PTL_RECE_POSITION prp
inner join VW_REPAY_WITHOUT_INT vrwi on vrwi.WITHOUT_BRANCH = prp.BRANCH and vrwi.FINPRODID = prp.FINPROD_ID
where

prp.FINPROD_ID = #{finprodId}
and vrwi.BRANCH = #{branch}
and prp.PORTFOLIO_ID = #{portfolioId}
and prp.SEC_ACCT_ID = #{secAcctId}
and prp.HODING_TYPE = #{POSITION_TYPE_SJ}
and prp.PAY_DATE < #{PLAT_DATE}
and prp.CDATE = #{PLAT_DATE}
union all
select
prp.BRANCH,
prp.REC_TYPE recType,
prp.AMOUNT +IFNULL((
select
sum(AMOUNT)
from PTL_RECE_POSITION_FLOW prpf
where

prpf.PORTFOLIO_ID = prp.PORTFOLIO_ID
and prpf.FINPROD_ID = prp.FINPROD_ID
and prpf.SEC_ACCT_ID = prp.SEC_ACCT_ID
and prpf.BRANCH = prp.BRANCH
and prpf.INV_AIM = prp.INV_AIM
and prpf.HODING_TYPE = #{POSITION_TYPE_KY}
and prpf.CDATE = prp.CDATE
),0) AMOUNT,
prp.CCY,
prp.INV_AIM
from
PTL_RECE_POSITION prp
where

prp.FINPROD_ID = #{finprodId}
and prp.BRANCH = #{branch}
and prp.PORTFOLIO_ID = #{portfolioId}
and prp.SEC_ACCT_ID = #{secAcctId}
and prp.HODING_TYPE = #{POSITION_TYPE_SJ}
and prp.PAY_DATE < #{PLAT_DATE}
and prp.CDATE = #{PLAT_DATE}

select IFNULL(sum(post.amount),0)amt  from VW_REPAY_WITHOUT_INT repay,PTL_RECE_POSITION post
where repay.BRANCH=#{branch}
and repay.WITHOUT_BRANCH=post.BRANCH
and repay.FINPRODID=post.FINPROD_ID
and  post.FINPROD_ID= #{finprodId}
and post.PORTFOLIO_ID=#{portfolioId}

    and post.SEC_ACCT_ID = #{chlId}


    and post.SEC_ACCT_ID = '999999'

and post.INV_AIM=#{INV_AIM}
and post.CDATE=#{PLAT_DATE}
and post.HODING_TYPE=#{POSITION_TYPE_SJ}
and rec_type='03'

select IFNULL(sum(post.amount),0)amount,
repay.WITHOUT_BRANCH BRANCH,
post.PORTFOLIO_ID
from VW_REPAY_WITHOUT_INT repay,PTL_RECE_POSITION post
where repay.WITHOUT_BRANCH=post.BRANCH
and repay.FINPRODID=post.FINPROD_ID
and  post.FINPROD_ID= #{finprodId}
and post.PORTFOLIO_ID=#{portfolioId}

    and post.SEC_ACCT_ID = #{chlId}


    and post.SEC_ACCT_ID = '999999'

and post.INV_AIM=#{INV_AIM}
and post.CDATE=#{PLAT_DATE}
and post.HODING_TYPE=#{POSITION_TYPE_SJ}
and rec_type=#{REC_TYPE_03}
group by repay.WITHOUT_BRANCH,post.PORTFOLIO_ID
